#include <iostream>
#include <concepts>

template <typename T>
concept Numeric = std::integral<T> || std::floating_point<T>;

template <Numeric T>
T add(T a, T b) {
    return a + b;
}

template <typename T>
concept HasSize = ___ (T a) {
    { a.size() } -> std::same_as<std::size_t>;
};

template <typename T>
concept Incrementable = requires(T a) {
    { ++a } ___ std::same_as<T&>;
};
